def compute(vars):
    total_route_miles = vars["v2"]
    owned_route_miles = vars["v1"]

    if total_route_miles == 0:
        return None

    owned_percentage = (owned_route_miles / total_route_miles) * 100

    return {
        "value": owned_percentage,
        "trace": {
            "owned_route_miles": owned_route_miles,
            "total_route_miles": total_route_miles,
            "owned_percentage": owned_percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
